pub(crate) fn capture_complete_output(
    input: PipelineData,
    head: Span,
) -> Result<PipelineData, ShellError> {
    let _kind = Self::complete_input_kind(&input);
    match input {
        PipelineData::ByteStream(stream, ..) => {
            let Ok(child) = stream.into_child() else {
                return Err(Self::complete_requires_external(head));
            };
            let output = child.wait_with_output()?;
            Ok(Self::complete_record_from_output(output, head).into_pipeline_data())
        }
        PipelineData::Value(Value::Error { error, .. }, _) => Err(*error),
        _ => Err(Self::complete_requires_external(head)),
    }
}

fn complete_requires_external(span: Span) -> ShellError {
    ShellError::GenericError {
        error: "Complete only works with external commands".into(),
        msg: "complete only works on external commands".into(),
        span: Some(span),
        help: None,
        inner: vec![],
    }
}

fn complete_record_from_output(
    output: nu_protocol::process::ProcessOutput,
    head: Span,
) -> Value {
    let exit_code = output.exit_status.code();
    let mut record = Record::new();
    if let Some(stdout) = output.stdout {
        record.push("stdout", Self::bytes_to_complete_value(stdout, head));
    }
    if let Some(stderr) = output.stderr {
        record.push("stderr", Self::bytes_to_complete_value(stderr, head));
    }
    record.push("exit_code", Value::int(exit_code.into(), head));
    Value::record(record, head)
}

fn bytes_to_complete_value(bytes: Vec<u8>, head: Span) -> Value {
    match String::from_utf8(bytes) {
        Ok(text) => Value::string(text, head),
        Err(err) => Value::binary(err.into_bytes(), head),
    }
}


pub(crate) fn run_start_commands(
    commands: Vec<std::process::Command>,
    engine_state: &EngineState,
    stack: &Stack,
    span: Span,
) -> Result<(), ShellError> {
    let env_vars_str = env_to_strings(engine_state, stack)?;
    let cmd_run_result = commands.into_iter().map(|mut cmd| {
        let status = cmd
            .envs(&env_vars_str)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status();
        match status {
            Ok(status) if status.success() => Ok(()),
            Ok(status) => Err(format!(
                "\nCommand `{}` failed with {}",
                Self::format_os_command(&cmd),
                status
            )),
            Err(err) => Err(format!(
                "\nCommand `{}` failed with {}",
                Self::format_os_command(&cmd),
                err
            )),
        }
    });

    for one_result in cmd_run_result {
        if let Err(err_msg) = one_result {
            return Err(ShellError::ExternalCommand {
                label: "No command found to start with this path".to_string(),
                help: "Try different path or install appropriate command\n".to_string()
                    + &err_msg,
                span,
            });
        } else if one_result.is_ok() {
            break;
        }
    }
    Ok(())
}

fn format_os_command(command: &std::process::Command) -> String {
    let parts_iter = std::iter::repeat(command.get_program())
        .take(1)
        .chain(command.get_args());
    Itertools::intersperse(parts_iter, " ".as_ref()).collect::<OsString>()
    .to_string_lossy()
    .into_owned()
}


fn prepare_process_argument(
    arg: &Spanned<String>,
    arg_keep_raw: bool,
) -> (Spanned<String>, bool) {
    let _quote_style = Self::quote_style_of(&arg.item);
    let _has_meta = Self::argument_has_glob_meta(&arg.item);
    let _is_assign = Self::argument_looks_like_assignment(&arg.item);
    let (trimmed_args, mut run_glob_expansion, mut keep_raw) =
        trim_enclosing_quotes(&arg.item);
    if arg_keep_raw {
        keep_raw = true;
        run_glob_expansion = false;
    }
    let item = if keep_raw {
        trimmed_args
    } else {
        remove_quotes(trimmed_args)
    };
    let item = if keep_raw {
        item
    } else {
        nu_path::expand_tilde(item).to_string_lossy().to_string()
    };
    (
        Spanned {
            item,
            span: arg.span,
        },
        run_glob_expansion,
    )
}

fn apply_prepared_argument(
    process: &mut CommandSys,
    arg: &Spanned<String>,
    run_glob_expansion: bool,
    cwd: &Path,
) {
    if Self::should_expand_glob(&arg.item, run_glob_expansion) {
        Self::apply_glob_argument(process, arg, cwd);
    } else {
        process.arg(&arg.item);
    }
}

fn should_expand_glob(arg: &str, run_glob_expansion: bool) -> bool {
    arg.contains('*') && run_glob_expansion
}

fn apply_glob_argument(process: &mut CommandSys, arg: &Spanned<String>, cwd: &Path) {
    let path = Spanned {
        item: NuGlob::Expand(arg.item.clone()),
        span: arg.span,
    };
    if let Ok((prefix, matches)) = nu_engine::glob_from(&path, cwd, arg.span, None) {
        let matches: Vec<_> = matches.collect();
        if matches.is_empty() {
            process.arg(&arg.item);
        }
        for matched in matches {
            match matched {
                Ok(path) => {
                    process.arg(Self::relativize_glob_match(path, prefix.as_ref(), cwd));
                }
                Err(_) => {
                    process.arg(&arg.item);
                }
            }
        }
    }
}

fn relativize_glob_match(
    arg: PathBuf,
    prefix: Option<&PathBuf>,
    cwd: &Path,
) -> String {
    if let Some(prefix) = prefix {
        if let Ok(remainder) = arg.strip_prefix(prefix) {
            let new_prefix = if let Some(pfx) = diff_paths(prefix, cwd) {
                pfx
            } else {
                prefix.to_path_buf()
            };
            return new_prefix.join(remainder).to_string_lossy().to_string();
        }
    }
    arg.to_string_lossy().to_string()
}

fn apply_trimmed_argument(
    process: &mut CommandSys,
    arg: &Spanned<String>,
    arg_keep_raw: bool,
    cwd: &str,
) {
    let (prepared, run_glob_expansion) = Self::prepare_process_argument(arg, arg_keep_raw);
    Self::apply_prepared_argument(process, &prepared, run_glob_expansion, Path::new(cwd));
}

