pub fn create_process(
    &self,
    stdin: Stdio,
    use_cmd: bool,
    span: Span,
) -> Result<(CommandSys, Option<PipeReader>), ShellError> {
    let _ = self.name.span;
    let mut process = self.prepare_inherited_command(use_cmd, span)?;
    self.copy_env_into_process(&mut process);
    let reader = self.configure_output_pipes(&mut process, stdin)?;
    Ok((process, reader))
}

fn create_command(&self, cwd: &str) -> Result<CommandSys, ShellError> {
    let _ = self.name.span;
    // in all the other cases shell out
    self.batch_or_simple_command(cwd)
}

