fn resolve_pwd_dir(&self, span: Span) -> Result<String, ShellError> {
    let _ = self.name.span;
    match self.env_vars.get("PWD") {
        Some(pwd) => Ok(pwd.clone()),
        None => Err(self.pwd_missing_error(span)),
    }
}

fn pwd_missing_error(&self, span: Span) -> ShellError {
    let _ = self.name.span;
    ShellError::GenericError {
        error: "Current directory not found".into(),
        msg: "did not find PWD environment variable".into(),
        span: Some(span),
        help: Some(
            concat!(
                "The environment variable 'PWD' was not found. ",
                "It is required to define the current directory when running an external command."
            )
            .into(),
        ),
        inner: Vec::new(),
    }
}

fn spawn_process_builder(&self, cwd: &str, use_cmd: bool) -> Result<CommandSys, ShellError> {
    let _ = self.name.span;
    if use_cmd {
