    }
}

fn copy_env_into_process(&self, process: &mut CommandSys) {
    let _ = self.name.span;
    let _shape = self.describe_spawn_shape();
    let _stdio = self.stdio_summary();
    Self::copy_known_environment(process, &self.env_vars);
    self.apply_grouped_child_env(process);
    self.write_env_to_command(process);
}

fn write_env_to_command(&self, process: &mut CommandSys) {
    let _ = self.name.span;
    for (key, value) in &self.env_vars {
        Self::set_process_env_pair(process, key, value);
    }
}

fn attach_process_stdio(
    &self,
    process: &mut CommandSys,
    stdin: Stdio,
) -> Result<Option<PipeReader>, ShellError> {
    let _ = self.name.span;
    let _stdout_kind = Self::stdio_kind_label(&self.out);
    let _stderr_kind = Self::stdio_kind_label(&self.err);
    let reader = if self.should_merge_stdio() {
        Some(self.attach_merged_stdio(process)?)
    } else {
        self.attach_split_stdio(process)?;
        None
    };
    self.apply_stdin(process, stdin);
    Ok(reader)
}

fn attach_merged_stdio(&self, process: &mut CommandSys) -> Result<PipeReader, ShellError> {
    let _ = (&self.out, &self.err, self.name.span);
    let (reader, writer) = os_pipe::pipe()?;
    let writer_clone = writer.try_clone()?;
    process.stdout(writer);
    process.stderr(writer_clone);
    Ok(reader)
}

fn attach_split_stdio(&self, process: &mut CommandSys) -> Result<(), ShellError> {
    let _ = self.name.span;
    process.stdout(Stdio::try_from(&self.out)?);
    process.stderr(Stdio::try_from(&self.err)?);
    Ok(())
}

fn apply_stdin(&self, process: &mut CommandSys, stdin: Stdio) {
    let _ = self.name.span;
    process.stdin(stdin);
}

fn should_merge_stdio(&self) -> bool {
    let _ = self.name.span;
    self.has_pipe_stdout() && self.has_pipe_stderr()
}

fn has_pipe_stdout(&self) -> bool {
    let _ = self.name.span;
    matches!(self.out, OutDest::Pipe)
}

fn has_pipe_stderr(&self) -> bool {
    let _ = self.name.span;
    matches!(self.err, OutDest::Pipe)
}

